export type SelinuxCheckpoint = {
    id: number;
    host_id: number;
    boot_id: string;
    event_time: string;
    evidence_class: 'observed_checkpoint';
    policy_identity: string | null;
    enforcement: string | null;
    /**
     * Only names relevant to linked change records. Values come from this checkpoint; absent or unobserved current state is null, never copied from a transition delta.
     */
    booleans: Array<{
        name: string;
        value: boolean | null;
    }>;
};

export type SelinuxActivityItem = {
    actor?: SelinuxActivityActor;
    id: number;
    host_id: number;
    boot_id: string;
    event_time: string;
    evidence_class: 'observed_transition' | 'administrative_history';
    transition_type: 'policy_load' | 'boolean_change' | 'enforcement_change' | 'port_change';
    boundary_established: boolean;
    audit_sequence: number;
    boolean_changes: Array<{
        name: string;
        old_value: boolean;
        new_value: boolean;
        state_change_established: boolean;
    }>;
    /**
     * Validated enabled-SELinux runtime enforcement fields; an unvalidated MAC_STATUS shape remains history without a delta or boundary.
     */
    enforcement_changes?: Array<{
        old_mode: 'enforcing' | 'permissive';
        new_mode: 'enforcing' | 'permissive';
        state_change_established: boolean;
    }>;
    /**
     * Validated port-write fields only. Delete omits type; modify has no old value and may be equal-value. Boundary does not claim a reconstructed mapping delta.
     */
    port_changes?: Array<{
        operation: 'add' | 'modify' | 'delete';
        protocol: 'tcp' | 'udp';
        start: number;
        end: number;
        target_context: string | null;
        selinux_type: string | null;
        success: boolean;
        boundary_established: boolean;
    }>;
    /**
     * Earlier historical checkpoint, not an assertion that it was current throughout the intervening period.
     */
    previous_checkpoint: SelinuxCheckpoint | null;
    reconciliation: {
        status: 'pending' | 'reconciled' | 'superseded' | 'not_applicable';
        /**
         * Affected dimensions lacking authoritative evidence in the projected checkpoint. A later incomplete observation does not establish reconciliation.
         */
        unreconciled_fields?: Array<'policy_identity' | 'booleans' | 'enforcement' | 'ports'>;
        /**
         * Earliest retained checkpoint authoritatively observing all affected dimensions, or the earliest later incomplete observation if no such checkpoint exists. A superseding transition may precede it; unknown fields are not inferred.
         */
        checkpoint: SelinuxCheckpoint | null;
        next_transition: {
            id: number;
            event_time: string;
            audit_sequence: number;
        } | null;
    };
    /**
     * Retained occurrences with unsafe affected checkpoint dimensions after this boundary, before an overlapping boundary, and at/before the earliest retained checkpoint. Different dimension intervals may overlap; counts are not additive.
     */
    window_avc_count: number;
};

