export type ListHostSelinuxActivityData = {
    body?: never;
    path: {
        id: number;
    };
    query?: {
        /**
         * Opaque cursor from meta.next_cursor; pages contain at most 20 administrative identities.
         */
        before?: string;
        /**
         * Positive page number for 10-row numbered pagination. Omit for cursor or selected-event navigation.
         */
        page?: number;
        /**
         * Select one supported administrative identity for cross-navigation, including older evidence.
         */
        event_id?: number;
        /**
         * Return the preceding boundary only when this host occurrence is in an unresolved interval; otherwise an empty page.
         */
        occurrence_id?: number;
    };
    url: '/api/v1/hosts/{id}/selinux-activity';
};

